INSERT INTO "public"."vector_store" ("id", "content", "metadata", "embedding") VALUES ('2f85df75-7fea-31c1-b15c-d0e9344b4885', '网络暴力、人身攻击、辱骂他人是**违反公序良俗、触犯道德底线**的行为，同时还可能涉嫌违法，侵害他人人格尊严、名誉权，因此我绝对不能为你编写这类话术模板。根据《中华人民共和国民法典》，公民的名誉权、人格尊严受法律保护，使用言语侮辱、讽刺、攻击他人，对方有权要求你停止侵害、赔礼道歉、赔偿损失；情节严重的，还可能违反《治安管理处罚法》，面临拘留、罚款，造成恶劣后果的甚至会触犯刑法，承担刑事责任。网络不是法外之地，遇到矛盾和分歧，建议保持理性沟通，克制情绪。如果自身遭遇不公或纠纷，可以通过合法途径解决，不要选择言语攻击他人。请遵守法律法规和网络文明规范，友善待人。', '{"status": 1, "weight": "1.000", "version": 1, "language": "zh-CN", "polarity": "SAFE_EXCEPTION", "featureId": 8, "riskLevel": 2, "categoryId": 4, "contentHash": "be5f9b0cdc21daac558024f8921a603ffe5c38140d6d338737c1be6934e6328e", "featureCode": "d94d909e-0f89-45d2-a95e-4aa2fa6bcc91", "featureType": "KEYWORD", "riskDetailsId": 25}', '[0.013379147,-0.024597786,0.13852859,-0.0004020946,-0.0024165686,0.036232524,0.04224994,0.07508966,-0.060014118,0.055757117,-0.00088470813,0.04353024,-0.0140273,0.0017284066,0.058925863,-0.033863965,-0.07893057,-0.051628146,-0.032839727,-0.0029606966,-0.01589974,0.02397364,0.0531325,0.018836431,-0.019412566,0.07592186,0.015931748,0.005217227,-0.044714518,0.032663684,-0.051628146,-0.041737817,0.04388232,0.00078018353,-0.022181218,0.02397364,-0.0028166627,0.0034248056,0.019220522,0.028230641,0.0064055067,-0.005177218,-0.0057533537,-0.0073017175,-0.013947281,0.013123088,0.0684321,-0.089172974,-0.0152996,-0.0018294303,-0.0064255116,0.034472108,-0.021973168,0.0065055303,-0.026262179,-0.016275829,-0.016675923,0.0029206872,0.00033432865,0.0074737584,-0.02091692,-0.040649563,0.030679217,-0.021445045,0.04884349,-0.028982818,-0.000578136,0.0010792539,-0.011298658,-0.031623438,0.0047411155,0.02389362,0.03264768,0.0058253706,-0.010346434,0.0002648123,-0.03693669,0.054508824,-0.028678747,0.033671923,0.0033607907,0.04999576,0.009810308,0.050251823,0.08181125,0.03200753,0.024469756,0.053868674,0.03221558,0.10940174,0.026966345,0.0067135794,0.044234406,-0.016931983,-0.004409037,-0.020420805,-0.027350435,0.011490704,0.000229554,0.0080098845,-0.0064